/*
 * A281746  Nonnegative numbers k such that k == 0 (mod 3) or k == 0 (mod 5).
 * https://oeis.org/A281746
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(1)=0, a(n) is the n‑th non‑negative integer divisible by 3 or
 *            5. It is generated by repeatedly taking the smallest multiple of
 *            3 or 5 larger than the previous term. This is equivalent to the
 *            definition “k == 0 (mod 3) or k == 0 (mod 5).” The function is
 *            memoised so that repeated calls are O(1)...
 * Range:     u8 n <= 120, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>   /* malloc, realloc, abort */
#include <stddef.h>   /* size_t */

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;   /* cached values, 1‑based offset */
    static size_t cache_len = 0;  /* number of stored terms */
    static seq_t last = 0;        /* last value generated (a(cache_len)) */

    /* Return cached term if already computed */
    if (n <= cache_len) {
        return cache[n - 1];
    }

    /* Allocate or grow the cache to fit the new index */
    size_t new_cap = n;
    if (!cache) {
        cache = (seq_t *)malloc(new_cap * sizeof(seq_t));
        if (!cache) abort();           /* out of memory */
        cache_len = 0;
        /* initialise first term a(1)=0 */
        cache[0] = 0;
        cache_len = 1;
        last = 0;
    } else if (new_cap > cache_len) {
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) abort();           /* out of memory */
        cache = tmp;
    }

    /* Generate terms up to the requested index */
    while (cache_len < n) {
        seq_t next3 = (last / (seq_t)3 + (seq_t)1) * (seq_t)3;
        seq_t next5 = (last / (seq_t)5 + (seq_t)1) * (seq_t)5;
        seq_t next = next3 < next5 ? next3 : next5;
        cache[cache_len++] = next;
        last = next;
    }

    return cache[n - 1];
}
